                  padding:'8px 4px',textAlign:'center',
                  fontSize:(.62*effScale)+'rem',fontWeight:700,
                  letterSpacing:'.1em',textTransform:'uppercase',
                  borderBottom:'1px solid rgba(255,255,255,.12)',
